3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single definition of household membership, shared by {@link EnsureUniqueOwnerHousehold}
9	 * (which rejects an unshared duplicate) and {@link AssignOwnerHousehold} (which assigns the
10	 * shared id), so the guard and the assignment agree by construction rather than by comment.
11	 * Two owners are in the same household when their lastName and address match, compared
12	 * case-insensitively with collapsed whitespace.
13	 */
14	final class OwnerHousehold {
15	
16	    private OwnerHousehold() {
17	    }
18	
19	    /** Whether an owner with the given lastName and address shares a household with {@code other}. */
20	    static boolean isSameHousehold(String lastName, String address, Owner other) {
21	        return normalize(lastName).equals(normalize(other.getLastName()))
22	                && normalize(address).equals(normalize(other.getAddress()));
23	    }
24	
25	    /** Lower-case and collapse whitespace runs to a single space for comparison. */
26	    private static String normalize(String value) {
27	        if (value == null) {
28	            return "";
29	        }
30	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
31	    }
32	}
