3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>} where
9	 * LAST3 is the upper-cased first three letters of the last name and NNNN is a global
10	 * 4-digit zero-padded sequence equal to one more than the current number of owners
11	 * (e.g. {@code SMI-0007}). Runs before the owner is saved, so the count excludes the
12	 * owner being created and successive creates receive consecutive sequence numbers.
13	 */
14	public class AssignCustomerCode {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String lastName = owner.getLastName();
18	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
19	        int sequence = ownerRepository.findAll().size() + 1;
20	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
21	    }
22	}
