132	        return this.pets;
133	    }
134	
135	    protected void setPetsInternal(Set<Pet> pets) {
136	        this.pets = pets;
137	    }
138	
139	    public List<Pet> getPets() {
140	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
141	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
