3	/**
4	 * Single definition of how an owner telephone is converted to E.164 form: strip spaces,
5	 * dashes and brackets; keep a leading '+' and country code when present, otherwise assume
6	 * country code '+61' and drop a single leading '0' from the national digits; require 8 to
7	 * 15 digits after the '+'. Both {@link NormalizeOwnerTelephone} (which normalizes the
8	 * incoming request) and {@link EnsureUniqueOwnerTelephone} (which normalizes stored owners
9	 * for comparison) call this, so the create-time rule and the dedup comparison can never
10	 * silently diverge.
11	 */
12	final class OwnerTelephones {
13	
14	    private OwnerTelephones() {
15	    }
16	
17	    /**
18	     * Converts {@code telephone} to its E.164 representation (e.g. "0412 345 678" ->
19	     * "+61412345678"), or returns {@code null} when it cannot form a valid E.164 number.
20	     */
21	    static String toE164(String telephone) {
22	        if (telephone == null) {
23	            return null;
24	        }
25	        // Strip spaces, dashes and brackets; anything else must already be digits (or the
26	        // leading '+'), so a stray character makes the digit test below fail.
27	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
28	        String digits;
29	        if (cleaned.startsWith("+")) {
30	            // Explicit country code: keep it, just take the following digits.
31	            digits = cleaned.substring(1);
32	        } else {
33	            // No country code: assume '+61' and drop a single leading '0' from the national part.
34	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
35	            digits = "61" + national;
36	        }
37	        if (!digits.matches("\\d{8,15}")) {
38	            return null;
39	        }
40	        return "+" + digits;
41	    }
42	}
